import hashlib
import math
import re


def tokenize(text):
    return re.findall(r"[a-z0-9]+", text.lower())


def hash_embed(text, dim=256):
    vec = [0.0] * dim
    for tok in tokenize(text):
        h = hashlib.md5(tok.encode()).digest()
        idx = int.from_bytes(h[:4], "big") % dim
        sign = 1.0 if h[4] % 2 else -1.0
        vec[idx] += sign
    norm = math.sqrt(sum(v * v for v in vec))
    if norm == 0:
        return vec
    return [v / norm for v in vec]


def cosine(a, b):
    return sum(x * y for x, y in zip(a, b))


def chunk_fixed(text, size, overlap=0):
    if size <= 0:
        raise ValueError("size must be positive")
    step = size - overlap
    if step <= 0:
        raise ValueError("overlap must be less than size")
    return [text[i:i + size] for i in range(0, len(text), step) if text[i:i + size].strip()]


def chunk_recursive(text, size, seps=("\n\n", "\n", ". ", " ")):
    if len(text) <= size:
        return [text.strip()] if text.strip() else []
    for sep in seps:
        if sep not in text:
            continue
        parts = text.split(sep)
        chunks = []
        buf = ""
        for p in parts:
            candidate = buf + sep + p if buf else p
            if len(candidate) <= size:
                buf = candidate
            else:
                if buf:
                    chunks.append(buf.strip())
                buf = p
        if buf:
            chunks.append(buf.strip())
        return [c for c in chunks if c]
    return chunk_fixed(text, size)


def split_sentences(text):
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    return [p.strip() for p in parts if p.strip()]


def chunk_semantic(text, threshold=0.3, min_chars=40):
    sentences = split_sentences(text)
    if not sentences:
        return []
    embs = [hash_embed(s) for s in sentences]
    chunks = [[sentences[0]]]
    for i in range(1, len(sentences)):
        sim = cosine(embs[i], embs[i - 1])
        if sim < threshold and len(" ".join(chunks[-1])) >= min_chars:
            chunks.append([sentences[i]])
        else:
            chunks[-1].append(sentences[i])
    return [" ".join(c) for c in chunks]


def chunk_sentence(text, sentences_per_chunk=3):
    sentences = split_sentences(text)
    return [" ".join(sentences[i:i + sentences_per_chunk])
            for i in range(0, len(sentences), sentences_per_chunk)]


def chunk_parent_child(text, parent_size=800, child_size=200):
    parents = chunk_recursive(text, size=parent_size)
    mapping = []
    for p_idx, parent in enumerate(parents):
        children = chunk_recursive(parent, size=child_size)
        for child in children:
            mapping.append({"child": child, "parent_idx": p_idx, "parent": parent})
    return mapping


def retrieve_recall(chunks, query, gold_substrings, top_k=3):
    chunk_embs = [hash_embed(c) for c in chunks]
    q_emb = hash_embed(query)
    scored = sorted([(cosine(e, q_emb), i) for i, e in enumerate(chunk_embs)], reverse=True)
    top_texts = [chunks[i] for _, i in scored[:top_k]]
    return any(any(g.lower() in c.lower() for g in gold_substrings) for c in top_texts)


def main():
    doc = """Chapter 1. Introduction. This contract is between Acme Corp and Beta Inc. The parties agree to the following terms.

Chapter 2. Payment. Acme will pay Beta thirty thousand dollars on the first of each month. Late payments incur a five percent fee.

Chapter 3. Termination. Either party may terminate this agreement with ninety days written notice. Termination for cause requires only thirty days notice. Breach of payment constitutes cause.

Chapter 4. Confidentiality. Both parties agree to keep trade secrets confidential. This obligation survives termination of the agreement.

Chapter 5. Miscellaneous. This agreement is governed by the laws of the State of California. Disputes shall be resolved by arbitration."""

    print("=== strategy comparison ===")
    print()

    fixed = chunk_fixed(doc, size=300, overlap=50)
    print(f"fixed (300 chars, 50 overlap):    {len(fixed)} chunks")

    rec = chunk_recursive(doc, size=300)
    print(f"recursive (300 chars):            {len(rec)} chunks")

    sem = chunk_semantic(doc)
    print(f"semantic (hash-trick):            {len(sem)} chunks")

    sent = chunk_sentence(doc, sentences_per_chunk=3)
    print(f"sentence (3 per chunk):           {len(sent)} chunks")

    pc = chunk_parent_child(doc, parent_size=800, child_size=200)
    parents = {m["parent_idx"] for m in pc}
    print(f"parent-child (800 / 200):         {len(pc)} children, {len(parents)} parents")

    queries = [
        ("When can either party terminate?", ["ninety days", "thirty days"]),
        ("What is the late payment fee?", ["five percent"]),
        ("Which state laws apply?", ["California"]),
    ]

    print()
    print("=== recall@3 on 3 queries ===")
    for name, chunks in [("fixed", fixed), ("recursive", rec), ("semantic", sem),
                         ("sentence", sent), ("parent", [m["parent"] for m in pc])]:
        hits = sum(retrieve_recall(chunks, q, gold) for q, gold in queries)
        print(f"  {name:<12}: {hits} / {len(queries)}")

    print()
    print("note: hash-trick embedder is noisy.")
    print("production embedders (BGE, text-3) give 20-40 pp higher recall on the same chunks.")


if __name__ == "__main__":
    main()

// Chunking strategies for RAG in TypeScript: fixed, recursive, semantic,
// sentence, parent-child. Mirrors code/main.py and follows the splitter
// hierarchy from LangChain.js (RecursiveCharacterTextSplitter).
// Sources:
//   https://docs.langchain.com/oss/javascript/integrations/splitters
//   https://philna.sh/blog/2024/09/18/how-to-chunk-text-in-javascript-for-rag-applications/
//   https://github.com/langchain-ai/langchainjs (textsplitters package)

import { createHash } from "node:crypto";

type Vec = readonly number[];

type ParentChildPair = {
  child: string;
  parentIdx: number;
  parent: string;
};

const TOKEN_RE = /[a-z0-9]+/g;

function tokenize(text: string): string[] {
  return text.toLowerCase().match(TOKEN_RE) ?? [];
}

function hashEmbed(text: string, dim = 256): Vec {
  if (dim <= 0) throw new Error("dim must be positive");
  // Hashing-trick embedder: every token contributes +/-1 to a hashed dim.
  // Deterministic, no training, useful as a stand-in for production
  // embedders (BGE-M3, text-embedding-3-small, voyage-3).
  const vec = new Array<number>(dim).fill(0);
  for (const tok of tokenize(text)) {
    const digest = createHash("md5").update(tok).digest();
    const idx = digest.readUInt32BE(0) % dim;
    const sign = digest[4] % 2 === 0 ? -1 : 1;
    vec[idx] += sign;
  }
  let norm = 0;
  for (const v of vec) norm += v * v;
  norm = Math.sqrt(norm);
  if (norm === 0) return vec;
  return vec.map((v) => v / norm);
}

function cosine(a: Vec, b: Vec): number {
  let dot = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) dot += a[i] * b[i];
  return dot;
}

function chunkFixed(text: string, size: number, overlap = 0): string[] {
  if (size <= 0) throw new Error("size must be positive");
  const step = size - overlap;
  if (step <= 0) throw new Error("overlap must be less than size");
  const out: string[] = [];
  for (let i = 0; i < text.length; i += step) {
    const piece = text.slice(i, i + size);
    if (piece.trim().length > 0) out.push(piece);
  }
  return out;
}

function chunkRecursive(
  text: string,
  size: number,
  seps: readonly string[] = ["\n\n", "\n", ". ", " "],
): string[] {
  if (size <= 0) throw new Error("size must be positive");
  // Mirrors LangChain.js RecursiveCharacterTextSplitter: try the strongest
  // separator first (paragraph), drop to weaker ones (sentence, word) when
  // the current pass leaves chunks larger than `size`.
  if (text.length <= size) {
    const t = text.trim();
    return t.length > 0 ? [t] : [];
  }
  for (const sep of seps) {
    if (!text.includes(sep)) continue;
    const parts = text.split(sep);
    const chunks: string[] = [];
    let buf = "";
    for (const part of parts) {
      const candidate = buf.length === 0 ? part : buf + sep + part;
      if (candidate.length <= size) {
        buf = candidate;
      } else {
        if (buf.length > 0) chunks.push(buf.trim());
        buf = part;
      }
    }
    if (buf.length > 0) chunks.push(buf.trim());
    return chunks.filter((c) => c.length > 0);
  }
  return chunkFixed(text, size);
}

function splitSentences(text: string): string[] {
  return text
    .trim()
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
}

function chunkSemantic(text: string, threshold = 0.3, minChars = 40): string[] {
  const sentences = splitSentences(text);
  if (sentences.length === 0) return [];
  const embs = sentences.map((s) => hashEmbed(s));
  const groups: string[][] = [[sentences[0]]];
  for (let i = 1; i < sentences.length; i += 1) {
    const sim = cosine(embs[i], embs[i - 1]);
    const current = groups[groups.length - 1];
    const joinedLen = current.join(" ").length;
    if (sim < threshold && joinedLen >= minChars) {
      groups.push([sentences[i]]);
    } else {
      current.push(sentences[i]);
    }
  }
  return groups.map((g) => g.join(" "));
}

function chunkSentence(text: string, sentencesPerChunk = 3): string[] {
  if (sentencesPerChunk <= 0) throw new Error("sentencesPerChunk must be positive");
  const sentences = splitSentences(text);
  const out: string[] = [];
  for (let i = 0; i < sentences.length; i += sentencesPerChunk) {
    out.push(sentences.slice(i, i + sentencesPerChunk).join(" "));
  }
  return out;
}

function chunkParentChild(text: string, parentSize = 800, childSize = 200): ParentChildPair[] {
  const parents = chunkRecursive(text, parentSize);
  const pairs: ParentChildPair[] = [];
  parents.forEach((parent, parentIdx) => {
    const children = chunkRecursive(parent, childSize);
    for (const child of children) {
      pairs.push({ child, parentIdx, parent });
    }
  });
  return pairs;
}

function retrieveRecall(
  chunks: readonly string[],
  query: string,
  goldSubstrings: readonly string[],
  topK = 3,
): boolean {
  const embs = chunks.map((c) => hashEmbed(c));
  const qEmb = hashEmbed(query);
  const scored = embs.map((e, i) => ({ score: cosine(e, qEmb), idx: i }));
  scored.sort((x, y) => y.score - x.score);
  const top = scored.slice(0, topK).map(({ idx }) => chunks[idx]);
  return top.some((c) => goldSubstrings.some((g) => c.toLowerCase().includes(g.toLowerCase())));
}

function main(): void {
  const doc = `Chapter 1. Introduction. This contract is between Acme Corp and Beta Inc. The parties agree to the following terms.

Chapter 2. Payment. Acme will pay Beta thirty thousand dollars on the first of each month. Late payments incur a five percent fee.

Chapter 3. Termination. Either party may terminate this agreement with ninety days written notice. Termination for cause requires only thirty days notice. Breach of payment constitutes cause.

Chapter 4. Confidentiality. Both parties agree to keep trade secrets confidential. This obligation survives termination of the agreement.

Chapter 5. Miscellaneous. This agreement is governed by the laws of the State of California. Disputes shall be resolved by arbitration.`;

  console.log("=== strategy comparison ===\n");

  const fixed = chunkFixed(doc, 300, 50);
  console.log("fixed (300 chars, 50 overlap):    " + fixed.length + " chunks");

  const rec = chunkRecursive(doc, 300);
  console.log("recursive (300 chars):            " + rec.length + " chunks");

  const sem = chunkSemantic(doc);
  console.log("semantic (hash-trick):            " + sem.length + " chunks");

  const sent = chunkSentence(doc, 3);
  console.log("sentence (3 per chunk):           " + sent.length + " chunks");

  const pc = chunkParentChild(doc, 800, 200);
  const parentSet = new Set(pc.map((m) => m.parentIdx));
  console.log("parent-child (800 / 200):         " + pc.length + " children, " + parentSet.size + " parents");

  const queries: ReadonlyArray<{ q: string; gold: readonly string[] }> = [
    { q: "When can either party terminate?", gold: ["ninety days", "thirty days"] },
    { q: "What is the late payment fee?", gold: ["five percent"] },
    { q: "Which state laws apply?", gold: ["California"] },
  ];

  console.log("\n=== recall@3 on 3 queries ===");
  const strategies: ReadonlyArray<{ name: string; chunks: readonly string[] }> = [
    { name: "fixed", chunks: fixed },
    { name: "recursive", chunks: rec },
    { name: "semantic", chunks: sem },
    { name: "sentence", chunks: sent },
    { name: "parent", chunks: Array.from(new Set(pc.map((m) => m.parent))) },
  ];
  for (const { name, chunks } of strategies) {
    const hits = queries.reduce((acc, { q, gold }) => acc + (retrieveRecall(chunks, q, gold) ? 1 : 0), 0);
    console.log("  " + name.padEnd(12) + ": " + hits + " / " + queries.length);
  }

  console.log("\nnote: hash-trick embedder is noisy.");
  console.log("production embedders (BGE, text-3) give 20-40 pp higher recall on the same chunks.");
}

main();

import re


PRONOUNS = {
    "he":    {"gender": "m", "number": "sg", "type": "prp"},
    "him":   {"gender": "m", "number": "sg", "type": "prp"},
    "his":   {"gender": "m", "number": "sg", "type": "prp"},
    "she":   {"gender": "f", "number": "sg", "type": "prp"},
    "her":   {"gender": "f", "number": "sg", "type": "prp"},
    "hers":  {"gender": "f", "number": "sg", "type": "prp"},
    "it":    {"gender": "n", "number": "sg", "type": "prp"},
    "its":   {"gender": "n", "number": "sg", "type": "prp"},
    "they":  {"gender": "u", "number": "pl", "type": "prp"},
    "them":  {"gender": "u", "number": "pl", "type": "prp"},
    "their": {"gender": "u", "number": "pl", "type": "prp"},
}

FEMALE_FIRST = {"mary", "alice", "sarah", "sophia", "emma", "olivia", "ava", "isabella", "maya", "jane"}
MALE_FIRST = {"john", "james", "david", "tim", "steve", "michael", "bob", "adam", "peter", "carl"}
NEUTER_HEADS = {"company", "firm", "corporation", "product", "device", "phone", "laptop", "computer",
                "organization", "team", "group", "agency", "bank"}


DETERMINERS = {"the", "a", "an"}


def extract_mentions(text):
    mentions = []
    for sent_idx, sent in enumerate(re.split(r"(?<=[.!?])\s+", text)):
        tokens = re.findall(r"[A-Za-z]+|[^\s]", sent)
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            low = tok.lower()
            if low in PRONOUNS:
                mentions.append({"text": tok, "span": (sent_idx, i),
                                 "type": "pronoun", "features": PRONOUNS[low]})
                i += 1
                continue
            if low in DETERMINERS and i + 1 < len(tokens):
                head = tokens[i + 1].lower()
                if head in NEUTER_HEADS:
                    mentions.append({"text": f"{tok} {tokens[i + 1]}", "span": (sent_idx, i),
                                     "type": "nominal",
                                     "features": {"gender": "n", "number": "sg", "head": head}})
                    i += 2
                    continue
            if tok[0].isupper() and tok.isalpha() and low not in DETERMINERS:
                j = i + 1
                while j < len(tokens) and tokens[j][0].isupper() and tokens[j].isalpha():
                    j += 1
                name = " ".join(tokens[i:j])
                gender = infer_gender(name)
                mentions.append({"text": name, "span": (sent_idx, i),
                                 "type": "ne", "features": {"gender": gender, "number": "sg"}})
                i = j
                continue
            i += 1
    return mentions


def infer_gender(name):
    first = name.split()[0].lower()
    if first in FEMALE_FIRST:
        return "f"
    if first in MALE_FIRST:
        return "m"
    return "u"


def agreement_score(mention, candidate):
    score = 0.0
    mf = mention["features"]
    cf = candidate["features"]
    if mf["number"] == cf["number"]:
        score += 1.0
    if mf["gender"] == "u" or cf["gender"] == "u" or mf["gender"] == cf["gender"]:
        score += 1.0
    else:
        score -= 2.0
    return score


def recency_score(mention, candidate):
    delta = (mention["span"][0] - candidate["span"][0]) * 2 + max(0, mention["span"][1] - candidate["span"][1]) * 0.01
    return -delta


def resolve(mentions):
    links = []
    for i, m in enumerate(mentions):
        if m["type"] != "pronoun":
            continue
        candidates = [c for c in mentions[:i] if c["type"] in ("ne", "nominal")]
        if not candidates:
            links.append((m, None))
            continue
        best = max(candidates, key=lambda c: agreement_score(m, c) + recency_score(m, c))
        links.append((m, best))
    return links


def clusters(mentions, links):
    parent = {id(m): id(m) for m in mentions}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        parent[find(a)] = find(b)

    for m, ant in links:
        if ant is not None:
            union(id(m), id(ant))
    groups = {}
    for m in mentions:
        root = find(id(m))
        groups.setdefault(root, []).append(m["text"])
    return list(groups.values())


def main():
    doc = (
        "Tim Cook walked onto the stage. "
        "He announced the new iPhone. "
        "The company also showed a laptop. "
        "It will ship in June. "
        "Mary Chen joined Apple last year. "
        "She leads the AI team. "
        "Her team built the voice assistant. "
        "The device impressed the audience."
    )

    print("=== toy rule-based coreference ===")
    print(f"document: {doc}")
    print()

    mentions = extract_mentions(doc)
    print(f"extracted {len(mentions)} mentions:")
    for m in mentions:
        print(f"  [{m['type']:<7}] {m['text']:<22} feats={m['features']}")

    print()
    links = resolve(mentions)
    print("pronoun links:")
    for pronoun, antecedent in links:
        ant_text = antecedent["text"] if antecedent else "<none>"
        print(f"  {pronoun['text']:<8} -> {ant_text}")

    print()
    print("clusters:")
    for i, cluster in enumerate(clusters(mentions, links)):
        if len(cluster) > 1:
            print(f"  cluster {i}: {cluster}")

    print()
    print("note: rules handle easy pronouns; production models are span-based neural.")
    print("note: neuter pronoun 'it' / 'its' prefers neuter-head nominals like 'the company'.")


if __name__ == "__main__":
    main()

import re
from collections import Counter


STOP = {"a", "an", "the", "is", "are", "was", "were", "of", "in", "on", "at",
        "to", "for", "with", "and", "or", "but", "this", "that", "by", "as"}


def tokenize(text):
    return [t for t in re.findall(r"[a-z0-9]+", text.lower()) if t not in STOP]


def split_sentences(text):
    return [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]


def faithfulness(answer, context):
    context_set = set(tokenize(context))
    claims = split_sentences(answer)
    if not claims:
        return 0.0
    supported = 0
    for claim in claims:
        claim_tokens = tokenize(claim)
        if not claim_tokens:
            continue
        overlap = sum(1 for t in claim_tokens if t in context_set)
        if overlap / len(claim_tokens) >= 0.5:
            supported += 1
    return supported / len(claims)


def answer_relevance(question, answer):
    q_tokens = set(tokenize(question))
    a_tokens = set(tokenize(answer))
    if not q_tokens or not a_tokens:
        return 0.0
    return len(q_tokens & a_tokens) / len(q_tokens | a_tokens)


def context_precision(retrieved_chunks, relevant_chunks):
    if not retrieved_chunks:
        return 0.0
    hits = sum(1 for c in retrieved_chunks if c in relevant_chunks)
    return hits / len(retrieved_chunks)


def context_recall(retrieved_chunks, gold_answer_tokens):
    retrieved_text = " ".join(retrieved_chunks)
    retrieved_set = set(tokenize(retrieved_text))
    if not gold_answer_tokens:
        return 0.0
    covered = sum(1 for t in gold_answer_tokens if t in retrieved_set)
    return covered / len(gold_answer_tokens)


def g_eval_correctness(actual, expected, threshold=0.5):
    a_claims = split_sentences(actual)
    e_set = set(tokenize(expected))
    if not a_claims:
        return 0.0
    supported = 0
    for c in a_claims:
        c_tokens = tokenize(c)
        if not c_tokens:
            continue
        overlap = sum(1 for t in c_tokens if t in e_set) / len(c_tokens)
        if overlap >= threshold:
            supported += 1
    return supported / len(a_claims)


def main():
    cases = [
        {
            "question": "When was the first iPhone released?",
            "context": [
                "Apple released the first iPhone on June 29, 2007.",
                "Steve Jobs announced the iPhone at Macworld in January 2007.",
            ],
            "answer": "The first iPhone was released on June 29, 2007.",
            "expected": "June 29, 2007",
            "gold_relevant": ["Apple released the first iPhone on June 29, 2007."],
        },
        {
            "question": "When was the first iPhone released?",
            "context": [
                "Apple released the first iPhone on June 29, 2007.",
                "The moon landing was in 1969.",
            ],
            "answer": "The first iPhone launched on June 29, 2006, shortly after the moon landing.",
            "expected": "June 29, 2007",
            "gold_relevant": ["Apple released the first iPhone on June 29, 2007."],
        },
        {
            "question": "When was the first iPhone released?",
            "context": [
                "Apple released the first iPhone on June 29, 2007.",
                "Android launched in 2008.",
            ],
            "answer": "Apple is a technology company based in Cupertino.",
            "expected": "June 29, 2007",
            "gold_relevant": ["Apple released the first iPhone on June 29, 2007."],
        },
    ]

    print("=== toy RAG eval: faithfulness / relevance / context precision & recall / G-Eval ===")
    print()
    for i, case in enumerate(cases):
        ctx_joined = " ".join(case["context"])
        f = faithfulness(case["answer"], ctx_joined)
        r = answer_relevance(case["question"], case["answer"])
        cp = context_precision(case["context"], case["gold_relevant"])
        cr = context_recall(case["context"], tokenize(case["expected"]))
        ge = g_eval_correctness(case["answer"], case["expected"])
        print(f"case {i}: {case['question']}")
        print(f"  answer:   {case['answer']}")
        print(f"  expected: {case['expected']}")
        print(f"  faithfulness        = {f:.2f}")
        print(f"  answer-relevance    = {r:.2f}")
        print(f"  context-precision   = {cp:.2f}")
        print(f"  context-recall      = {cr:.2f}")
        print(f"  g-eval correctness  = {ge:.2f}")
        print()

    print("interpretation:")
    print("  case 0 = faithful + correct      -> all metrics high")
    print("  case 1 = hallucinated date        -> g-eval drops, faithfulness partial")
    print("  case 2 = off-topic answer         -> relevance + g-eval collapse")
    print()
    print("note: toy uses lexical overlap. production uses NLI + LLM-as-judge.")
    print("shape of the eval loop is identical.")


if __name__ == "__main__":
